// Motion thumbnails for the project cards. Supportive abstract
// looping animations (not product UI), placeholders until real
// demo videos replace them. v2 Nov 16, 2026: Kareer uses the
// real lime K logo, Syllabus Sync uses the real gold app icon,
// each project has its own colors (not all copper). CurlAI v3
// is a simple stickman curling with a counter. All loops are
// ping-pong (forward + reverse) for a seamless loop, 480x480,
// 4s, H.264, video-only (no audio track) and the card video
// element is muted. Embedded as data URIs because push_files
// cannot push binary files. LEGEND keeps its real school video.

export const KAREER_THUMB_MP4 = 'data:video/mp4;base64,';
